    code: ['if (++n % 100 === 0) spin(50)   // 1% slow', 'else spin(0.2)', ['// 요청을 하나씩 15초 동안 보내요', '// one request at a time for 15 s'], ['// 평균 하나로 말할 수 있을까?', '// can one average describe it?'], 'mean · p50 · p90 · p99 · p99.9 · max'],
    hl: [[0, 2, 'accent'], [4, 1, 'warn'], null, null],
