    code: ['node work.mjs', 'node --cpu-prof work.mjs', 'node --cpu-prof --cpu-prof-interval 100', 'node --cpu-prof --cpu-prof-interval 10', ['// 설정마다 7번 실행한 중앙값', '// median of 7 runs per setting']],
