function sSmallNT() {
  return CW('pf-small-n', {
    code: ['arr.includes(x)          // linear', 'bsearch(sorted, x)       // log n', 'set.has(x)               // hash', ['// 원소 4 · 16 · 64 · 256 · 4,096개', '// 4 · 16 · 64 · 256 · 4,096 elements'], ['// 조회 200만 번, 한 번에 걸린 시간', '// 2M lookups, time per lookup']],
    hl: [[0, 3, 'accent'], [0, 1, 'danger'], [2, 1, 'ok'], null],
    draw: (S) => {
      mono(S, 'm1', 19.0, .5, nbs(['n          4    16    64   256  4096', 'includes  4.0  6.1  15.4  78.3  2191', 'bsearch   3.7  6.9  10.7  12.9  16.8', 'Set       4.0  7.1   8.5   6.9   6.8']), 1, { w: 12.4, dy: .55, c: 'pfx-g' });
      lbl(S, 'l1', 19.0, 2.85, ['원소 16개까지는 셋 다 4~7ns로 같았어요', 'up to 16 elements, all three took the same 4–7 ns'], 'g', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.25, ['4,096개에서 includes는 2,191ns로, Set의 320배가 됐어요', 'at 4,096, includes took 2,191 ns, 320× the Set'], 'r', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.65, ['작은 목록은 단순한 배열로 충분하고, 커질 때 자료 구조를 바꿔요', 'small lists are fine as arrays; change the structure as they grow'], 'a', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['빅오는 n이 클 때의 이야기예요', 'big-O describes what happens when n is large'], 'a', 4, { w: 16.0 });
    },
    notes: [['값이 목록에 있는지 확인하는 방법 세 가지를 비교했어요 · 배열의 includes는 처음부터 차례로 보고, 이진 탐색은 정렬된 배열을 반씩 나누고, Set은 해시로 바로 찾아요 · 원소 수를 4개부터 4,096개까지 바꿔 가며 조회 200만 번의 평균을 쟀어요', 'three ways to check whether a value is in a list were compared, includes scanning an array from the start, binary search halving a sorted array, and a Set finding it directly by hash, averaging two million lookups as the element count ranged from 4 to 4,096'], ['원소 4개에서는 includes 4.0ns, 이진 탐색 3.7ns, Set 4.0ns였어요 · 16개에서도 6.1ns, 6.9ns, 7.1ns로 비슷했어요 · 이 크기에서는 빅오의 차이보다 함수 호출과 비교 몇 번의 상수가 시간을 정해요', 'with 4 elements, includes took 4.0 ns, binary search 3.7 ns and Set 4.0 ns, and with 16 they were a similar 6.1, 6.9 and 7.1 ns, constants such as a function call and a few comparisons setting the time at this size rather than differences in big-O'], ['원소가 늘자 갈렸어요 · includes는 64개에서 15.4ns, 256개에서 78.3ns, 4,096개에서 2,191ns로 원소 수에 비례해 늘었어요 · 이진 탐색은 16.8ns, Set은 6.8ns에 머물렀어요 · 4,096개에서 includes는 Set의 320배예요', 'as elements grew they parted ways: includes rose in proportion, to 15.4 ns at 64, 78.3 ns at 256 and 2,191 ns at 4,096, while binary search stayed at 16.8 ns and Set at 6.8 ns, includes at 4,096 being 320 times the Set'], ['빅오는 n이 커질 때 어떻게 늘어나는지를 말해요 · n이 작으면 상수가 더 중요해요 · 설정 값 몇 개, 상태 몇 개처럼 늘 작은 목록은 배열이 읽기 쉽고 충분히 빨라요 · 사용자 수나 상품 수처럼 커질 수 있는 목록이라면 처음부터 Set이나 Map을 써요', 'big-O describes how cost grows as n gets large, and at small n constants matter more, so lists that always stay small, such as a few settings or states, are fine as easy-to-read arrays, while lists that can grow, such as users or products, use a Set or Map from the start']],
    fin: [['작은 n에서는 같아요', 'equal at small n', 'pfx-xs pfx-a'], ['4,096개에서 320배', '320× at 4,096'], ['커질 목록은 Set으로', 'Sets for growing lists']],
    caps: [['세 가지 조회', 'Three lookups'], ['작은 목록', 'Small lists'], ['갈라지는 시간', 'Times diverging'], ['빅오와 상수', 'Big-O and constants'], ['작은 n의 탐색', 'Lookups at small n']]
  });
}

