      lbl(S, 'l1', 19.0, 3.4, ['같은 100만 개라도 무작위는 356ms, 이미 정렬된 입력은 76ms였어요', 'a million numbers: 356 ms when random, 76 ms when already sorted'], 'a', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.8, ['V8의 정렬은 이미 정렬된 구간을 찾아 이어 붙여, 거의 정렬된 입력에 빨라요', 'V8’s sort finds sorted runs and merges them, so nearly sorted input is fast'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.2, ['Float64Array는 비교 함수 없이 정렬해 무작위 64ms, 정렬됨 18ms였어요', 'Float64Array sorts without a comparator: 64 ms random, 18 ms sorted'], 'w', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['같은 알고리즘도 입력의 모양에 따라 달라요', 'the same algorithm depends on the shape of its input'], 'a', 4, { w: 16.0 });
