      lbl(S, 'l1', 19.0, 2.85, ['10만 × 1만에서 find는 1.7초, Map은 39ms로 43배 차이였어요', 'at 100k × 10k, find took 1.7 s and Map 39 ms, 43× apart'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.25, ['find는 주문마다 사용자를 처음부터 훑어, 주문 수 × 사용자 수만큼 비교해요', 'find scans users from the start for every order: orders × users comparisons'], 'w', 2, { w: 12.4 });
