      lbl(S, 'l3', 19.0, 6.2, ['워커 하나를 띄우는 데만 33ms가 들어, 짧은 일에는 손해예요', 'starting one worker took 33 ms, a loss for short jobs'], 'w', 3, { w: 12.4 });
